// crux-ai is a simple CLI demonstrating the crux-ai library.
package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"
	"time"

	"crux-ai/ai"
	"crux-ai/core"

	// Force provider registration via init()
	_ "crux-ai/providers"
)

func main() {
	if len(os.Args) < 2 {
		printUsage()
		os.Exit(1)
	}

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	switch os.Args[1] {
	case "models":
		handleModels()
	case "providers":
		handleProviders()
	case "complete":
		if len(os.Args) < 4 {
			fmt.Fprintf(os.Stderr, "Usage: crux-ai complete <provider> <model> [prompt]\n")
			os.Exit(1)
		}
		prompt := "Hello!"
		if len(os.Args) > 4 {
			prompt = os.Args[4]
		}
		handleComplete(ctx, os.Args[2], os.Args[3], prompt)
	default:
		fmt.Fprintf(os.Stderr, "Unknown command: %s\n", os.Args[1])
		printUsage()
		os.Exit(1)
	}
}

func printUsage() {
	fmt.Println("Usage: crux-ai <command>")
	fmt.Println()
	fmt.Println("Commands:")
	fmt.Println("  models                              List available models")
	fmt.Println("  providers                           List registered API providers")
	fmt.Println("  complete <provider> <model> [prompt] Run a completion")
}

func handleModels() {
	for _, provider := range ai.GetProviders() {
		fmt.Printf("── %s ──\n", provider)
		for _, m := range ai.GetModels(provider) {
			fmt.Printf("  %-40s %s\n", m.ID, m.Name)
		}
	}
}

func handleProviders() {
	for _, api := range core.GetRegisteredProviders() {
		fmt.Printf("  %s\n", api)
	}
}

func handleComplete(ctx context.Context, providerID, modelID, prompt string) {
	provider := core.KnownProvider(providerID)
	model, err := ai.GetModel(provider, modelID)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	msgs := []core.Message{
		core.UserMessage{Role: "user", Content: prompt, Timestamp: time.Now()},
	}

	stream, err := ai.StreamSimple(ctx, model, msgs)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	result, err := stream.ForEach(ctx, func(evt core.AssistantMessageEvent) error {
		switch e := evt.(type) {
		case core.EventTextDelta:
			fmt.Print(e.Delta)
		case core.EventThinkingDelta:
			fmt.Fprintf(os.Stderr, "[thinking] %s", e.Delta)
		}
		return nil
	})

	fmt.Println()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	fmt.Fprintf(os.Stderr, "\nTokens: %d in / %d out\n", result.Usage.Input, result.Usage.Output)
}

// Package ai provides the AI calling layer: public streaming/completion API,
// model management, and environment variable resolution.
package ai

import (
	"context"

	"crux-ai/core"
)

// Stream starts a streaming completion request.
func Stream(ctx context.Context, model core.Model, msgs []core.Message, opts ...core.StreamOptions) (*core.EventStream[core.AssistantMessageEvent, core.AssistantMessage], error) {
	provider, err := core.GetProvider(model.API)
	if err != nil {
		return nil, err
	}

	var opt core.StreamOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	c := core.Context{Messages: msgs}
	return provider.Stream(ctx, model, c, opt)
}

// Complete calls Stream and waits for the final result.
func Complete(ctx context.Context, model core.Model, msgs []core.Message, opts ...core.StreamOptions) (core.AssistantMessage, error) {
	s, err := Stream(ctx, model, msgs, opts...)
	if err != nil {
		return core.AssistantMessage{}, err
	}
	return s.Result()
}

// StreamSimple starts a streaming completion with simplified reasoning options.
func StreamSimple(ctx context.Context, model core.Model, msgs []core.Message, opts ...core.SimpleStreamOptions) (*core.EventStream[core.AssistantMessageEvent, core.AssistantMessage], error) {
	provider, err := core.GetProvider(model.API)
	if err != nil {
		return nil, err
	}

	var opt core.SimpleStreamOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	c := core.Context{Messages: msgs}
	return provider.StreamSimple(ctx, model, c, opt)
}

// StreamSimpleWithContext starts a streaming completion with full context (including tools and system prompt).
func StreamSimpleWithContext(ctx context.Context, model core.Model, llmCtx core.Context, opts ...core.SimpleStreamOptions) (*core.EventStream[core.AssistantMessageEvent, core.AssistantMessage], error) {
	provider, err := core.GetProvider(model.API)
	if err != nil {
		return nil, err
	}

	var opt core.SimpleStreamOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	return provider.StreamSimple(ctx, model, llmCtx, opt)
}

// CompleteSimple calls StreamSimple and waits for the final result.
func CompleteSimple(ctx context.Context, model core.Model, msgs []core.Message, opts ...core.SimpleStreamOptions) (core.AssistantMessage, error) {
	s, err := StreamSimple(ctx, model, msgs, opts...)
	if err != nil {
		return core.AssistantMessage{}, err
	}
	return s.Result()
}

// GenerateImages generates images using the specified image model.
func GenerateImages(ctx context.Context, model core.ImagesModel, msgs []core.Message, opts ...core.ImageOptions) (core.AssistantImages, error) {
	provider, err := core.GetImagesProvider(model.API)
	if err != nil {
		return core.AssistantImages{}, err
	}

	var opt core.ImageOptions
	if len(opts) > 0 {
		opt = opts[0]
	}

	c := core.Context{Messages: msgs}
	result, err := provider.GenerateImages(model, c, opt)
	if err != nil {
		return core.AssistantImages{}, err
	}
	return *result, nil
}

package ai

import (
	"fmt"
	"sync"

	"crux-ai/core"
)

var (
	modelsMap = make(map[core.KnownProvider]map[string]core.Model)
	modelsMu  sync.RWMutex
)

// LoadModels loads models into the registry. Called during init with generated data.
func LoadModels(models map[core.KnownProvider]map[string]core.Model) {
	modelsMu.Lock()
	defer modelsMu.Unlock()
	modelsMap = models
}

// GetModel looks up a model by provider and model ID.
func GetModel(provider core.KnownProvider, modelID string) (core.Model, error) {
	modelsMu.RLock()
	defer modelsMu.RUnlock()

	providerModels, ok := modelsMap[provider]
	if !ok {
		return core.Model{}, fmt.Errorf("unknown provider: %s", provider)
	}

	model, ok := providerModels[modelID]
	if !ok {
		return core.Model{}, fmt.Errorf("unknown model: %s/%s", provider, modelID)
	}

	return model, nil
}

// GetProviders returns all registered provider names.
func GetProviders() []core.KnownProvider {
	modelsMu.RLock()
	defer modelsMu.RUnlock()

	providers := make([]core.KnownProvider, 0, len(modelsMap))
	for p := range modelsMap {
		providers = append(providers, p)
	}
	return providers
}

// GetModels returns all models for a given provider.
func GetModels(provider core.KnownProvider) []core.Model {
	modelsMu.RLock()
	defer modelsMu.RUnlock()

	providerModels, ok := modelsMap[provider]
	if !ok {
		return nil
	}

	models := make([]core.Model, 0, len(providerModels))
	for _, m := range providerModels {
		models = append(models, m)
	}
	return models
}

// GetSupportedThinkingLevels returns the thinking levels supported by a model.
func GetSupportedThinkingLevels(model core.Model) []core.ThinkingLevel {
	if !model.Reasoning {
		return nil
	}

	if model.ThinkingLevelMap != nil {
		levels := make([]core.ThinkingLevel, 0, len(model.ThinkingLevelMap))
		for level := range model.ThinkingLevelMap {
			levels = append(levels, core.ThinkingLevel(level))
		}
		return levels
	}

	return []core.ThinkingLevel{core.ThinkingLow, core.ThinkingMedium, core.ThinkingHigh}
}

// ClampThinkingLevel finds the closest supported thinking level.
func ClampThinkingLevel(model core.Model, level core.ThinkingLevel) core.ThinkingLevel {
	supported := GetSupportedThinkingLevels(model)
	if len(supported) == 0 {
		return core.ThinkingMedium
	}

	for _, s := range supported {
		if s == level {
			return level
		}
	}

	levelOrder := []core.ThinkingLevel{core.ThinkingMinimal, core.ThinkingLow, core.ThinkingMedium, core.ThinkingHigh, core.ThinkingXHigh}
	targetIdx := -1
	for i, l := range levelOrder {
		if l == level {
			targetIdx = i
			break
		}
	}

	if targetIdx < 0 {
		targetIdx = 2
	}

	bestIdx := -1
	bestDist := len(levelOrder) + 1
	for _, s := range supported {
		for i, l := range levelOrder {
			if l == s {
				dist := abs(i - targetIdx)
				if dist < bestDist {
					bestDist = dist
					bestIdx = i
				}
			}
		}
	}

	if bestIdx >= 0 {
		return levelOrder[bestIdx]
	}

	return supported[0]
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

// ModelsAreEqual compares two models by id and provider.
func ModelsAreEqual(a, b core.Model) bool {
	return a.ID == b.ID && a.Provider == b.Provider
}

