	ProviderMoonshot:      {"MOONSHOT_API_KEY"},
	ProviderMoonshotCN:    {"MOONSHOT_API_KEY"},
	ProviderMinimax:       {"MINIMAX_API_KEY"},
	ProviderMinimaxCN:     {"MINIMAX_API_KEY"},
	ProviderXiaomi:        {"XIAOMI_API_KEY", "MI_API_KEY"},
}

// ResolveAPIKey resolves an API key from options or environment.
func ResolveAPIKey(provider KnownProvider, optsKey string) string {
	if optsKey != "" {
		return optsKey
	}
	return GetEnvAPIKey(provider)
}

// ResolveBaseURL resolves the base URL for a provider, with fallback.
func ResolveBaseURL(model Model, defaultURL string) string {
	if model.BaseURL != "" {
		return strings.TrimRight(model.BaseURL, "/")
	}
	return strings.TrimRight(defaultURL, "/")
}

// Package core 提供 AI provider 抽象��?package core

import (
	"context"
	"errors"
	"fmt"
	"net/http"
	"strings"
	"time"
)

// ============================================================================
// 错误分类系统
//
// 参��?oh-my-pi (packages/ai/src/utils/retry.ts) 的设计：
//   - 错误按来��?类型分类，不是每��?provider 自己��?retry
//   - retry 决策��?provider 实现解耦，通过接口组合
// ============================================================================

// ErrorKind 表示一个分类后的错误类��?type ErrorKind int

const (
	ErrorKindUnknown       ErrorKind = iota
	ErrorKindRateLimit                // 429 ��?速率限制
	ErrorKindOverloaded               // 500/503 ��?服务端过��?	ErrorKindAuth                     // 401/403 ��?认证/授权失败
	ErrorKindModelNotFound            // 404 ��?模型不存��?	ErrorKindContextLength            // 上下文超长（400+特殊 code��?	ErrorKindTimeout                  // 请求超时
	ErrorKindBadRequest               // 400（不可重试）
	ErrorKindServerError              // 500（非过载，不可重试）
)

// ErrorKind 的中文描��?func (k ErrorKind) String() string {
	switch k {
	case ErrorKindRateLimit:
		return "rate_limit"
	case ErrorKindOverloaded:
		return "overloaded"
	case ErrorKindAuth:
		return "auth"
	case ErrorKindModelNotFound:
		return "model_not_found"
	case ErrorKindContextLength:
		return "context_length"
	case ErrorKindTimeout:
		return "timeout"
	case ErrorKindBadRequest:
		return "bad_request"
	case ErrorKindServerError:
		return "server_error"
	default:
		return "unknown"
	}
}

// IsRetryable 返回该错误类型是否可重试��?// 参��?omp ��?isRetryableError() 逻辑��?func (k ErrorKind) IsRetryable() bool {
	switch k {
	case ErrorKindRateLimit, ErrorKindOverloaded, ErrorKindTimeout:
		return true
	default:
		return false
	}
}

// ProviderError 携带分类信息的错误��?// provider 在返回错误时应该��?NewProviderError 包裹，自动分类��?type ProviderError struct {
	Kind     ErrorKind
	Message  string
	HTTPCode int
	Wrapped  error
}

func (e *ProviderError) Error() string {
	if e.Wrapped != nil {
		return fmt.Sprintf("[%s] %s: %v", e.Kind, e.Message, e.Wrapped)
	}
	return fmt.Sprintf("[%s] %s", e.Kind, e.Message)
}

func (e *ProviderError) Unwrap() error {
	return e.Wrapped
}

// NewProviderError 创建一个分类后��?provider 错误��?// 自动根据 HTTP 状态码推断错误类型��?func NewProviderError(httpCode int, message string, wrapped error) *ProviderError {
	kind := classifyHTTPCode(httpCode)
	return &ProviderError{
		Kind:     kind,
		Message:  message,
		HTTPCode: httpCode,
		Wrapped:  wrapped,
	}
}

// IsRetryableProviderError 判断一��?error 是否是分类后的可重试错误��?func IsRetryableProviderError(err error) bool {
	var pe *ProviderError
	if errors.As(err, &pe) {
		return pe.Kind.IsRetryable()
	}
	// 未分类的错误也保守判��?	return false
}

// ExtractErrorKind 提取错误分类，未分类的返��?ErrorKindUnknown��?func ExtractErrorKind(err error) ErrorKind {
	var pe *ProviderError
	if errors.As(err, &pe) {
		return pe.Kind
	}
	return ErrorKindUnknown
}

// classifyHTTPCode 根据 HTTP 状态码返回错误分类��?func classifyHTTPCode(code int) ErrorKind {
	switch {
	case code == http.StatusTooManyRequests: // 429
		return ErrorKindRateLimit
	case code == http.StatusUnauthorized, code == http.StatusForbidden: // 401, 403
		return ErrorKindAuth
	case code == http.StatusNotFound: // 404
		return ErrorKindModelNotFound
	case code == http.StatusBadRequest: // 400
		return ErrorKindBadRequest // 大部��?400 不可重试
	case code == http.StatusServiceUnavailable || code == http.StatusBadGateway || code == http.StatusGatewayTimeout:
		return ErrorKindOverloaded // 503, 502, 504
	case code >= 500:
		return ErrorKindServerError
	default:
		return ErrorKindUnknown
	}
}

// Retryable 标识一个错误可以重试的接口��?// 实现该接口的类型可以用在重试装饰器中��?type Retryable interface {
	Retryable() bool
}

// ============================================================================
// 可组合的重试装饰��?//
// 参��?omp ��?callWithCopilotModelRetry() 设计��?//   - WrapRetry 不侵��?provider 代码
//   - 支持分层重试策略
//   - provider 可以通过 IsRetryableProviderError ��?Retryable 接口自定义重试决��?// ============================================================================

// RetryPolicy 定义重试策略��?type RetryPolicy struct {
	// MaxAttempts 最大尝试次数（包括第一次）。默��?3��?	MaxAttempts int
	// InitialBackoff 首次退避时间。默��?1s��?	InitialBackoff time.Duration
	// MaxBackoff 最大退避时间。默��?30s��?	MaxBackoff time.Duration
	// BackoffFactor 退避增长因子。默��?2��?	BackoffFactor float64
	// ShouldRetry 可选的判重函数。返��?true 表示应该重试��?	// ��?nil 时使用默认的 IsRetryableProviderError��?	ShouldRetry func(error) bool
	// OnRetry 每次重试前的回调（可用于日志记录）��?	OnRetry func(attempt int, err error)
}

// DefaultRetryPolicy 返回默认重试策略��?//
//	MaxAttempts: 3
//	InitialBackoff: 1s
//	MaxBackoff: 30s
//	BackoffFactor: 2
//	ShouldRetry: IsRetryableProviderError
func DefaultRetryPolicy() RetryPolicy {
	return RetryPolicy{
		MaxAttempts:    3,
		InitialBackoff: 1 * time.Second,
		MaxBackoff:     30 * time.Second,
		BackoffFactor:  2.0,
		ShouldRetry:    IsRetryableProviderError,
	}
}

// WrapRetry 包裹一个函数，按照 RetryPolicy 自动重试��?//
// 使用方式��?//
//	policy := DefaultRetryPolicy()
//	policy.OnRetry = func(attempt int, err error) {
//	    log.Printf("retry attempt %d: %v", attempt, err)
//	}
//	result, err := WrapRetry(ctx, policy, func(ctx context.Context) (AssistantMessage, error) {
//	    return provider.Stream(ctx, ...)
//	})
func WrapRetry[T any](ctx context.Context, policy RetryPolicy, fn func(context.Context) (T, error)) (T, error) {
	// 设置默认��?	if policy.MaxAttempts <= 0 {
		policy.MaxAttempts = 3
	}
	if policy.InitialBackoff <= 0 {
		policy.InitialBackoff = 1 * time.Second
	}
	if policy.MaxBackoff <= 0 {
		policy.MaxBackoff = 30 * time.Second
	}
	if policy.BackoffFactor <= 0 {
		policy.BackoffFactor = 2.0
	}
	if policy.ShouldRetry == nil {
		policy.ShouldRetry = IsRetryableProviderError
	}

	var lastErr error
	backoff := policy.InitialBackoff

	for attempt := 0; attempt < policy.MaxAttempts; attempt++ {
		if ctx.Err() != nil {
			var zero T
			return zero, ctx.Err()
		}

		result, err := fn(ctx)
		if err == nil {
			return result, nil
		}
		lastErr = err

		// 判断是否应该重试
		if !policy.ShouldRetry(err) {
			break
		}

		// 最后一次尝试失败后不再等待
		if attempt == policy.MaxAttempts-1 {
			break
		}

		if policy.OnRetry != nil {
			policy.OnRetry(attempt+1, err)
		}

		// 对于速率限制错误，等��?分钟
		waitTime := backoff
		if ExtractErrorKind(err) == ErrorKindRateLimit {
			waitTime = 5 * time.Minute
		}

		// 等待，注��?context 取消
		select {
		case <-ctx.Done():
			var zero T
			return zero, ctx.Err()
		case <-time.After(waitTime):
		}

		// 非速率限制错误使用指数退��?		if ExtractErrorKind(err) != ErrorKindRateLimit {
			backoff = time.Duration(float64(backoff) * policy.BackoffFactor)
			if backoff > policy.MaxBackoff {
				backoff = policy.MaxBackoff
			}
		}
	}

	var zero T
	return zero, lastErr
}

// ============================================================================
// Provider 特定的错误辅助函��?//
// 参��?omp ��?single-provider 级别的特��?retry 逻辑��?//   - isCopilotTransientModelError() ��?GitHub Copilot ��?400 model_not_supported
//   - 这些函数适合��?provider 实现中调��?// ============================================================================

// IsHTTPCodeError 检查错误是否来��?HTTP 状态码��?func IsHTTPCodeError(err error, code int) bool {
	var pe *ProviderError
	if errors.As(err, &pe) {
		return pe.HTTPCode == code
	}
	return false
}

// IsTransient400Error 检查是否是特定 API 返回��?瞬��?400"错误��?// 有些 provider（如 GitHub Copilot）在某些情况下会返回 400 但实际可以重试��?// 调用方通过 providerID 来判断��?func IsTransient400Error(err error, transientCodes ...string) bool {
	if !IsHTTPCodeError(err, http.StatusBadRequest) {
		return false
	}
	if len(transientCodes) == 0 {
		return false
	}
	msg := err.Error()
	for _, code := range transientCodes {
		if strings.Contains(msg, code) {
			return true
		}
	}
	return false
}

// NewContextError 构造上下文超长错误，便��?error propagation 时携带分类��?func NewContextError(message string, wrapped error) *ProviderError {
	return &ProviderError{
		Kind:    ErrorKindContextLength,
		Message: message,
		Wrapped: wrapped,
	}
}

// Package core 提供流式超时控制
//
// 参��?oh-my-pi (packages/ai/src/utils/idle-iterator.ts) 的设计：
//   双阶段超��?
//     1. firstEventTimeout: 从开始流到收到第一个事件的时间
//     2. idleTimeout: 事件之间的最大间��?//
// 心跳/keepalive 事件通过 isProgressItem 区分——不重置 idle 计时器，
// 防止"服务器一直发心跳但模型实际卡住了"��?
package core

import (
	"context"
	"errors"
	"fmt"
	"time"
)

// ============================================================================
// 超时配置
// ============================================================================

// StreamTimeoutConfig 定义流式请求的双阶段超时策略��?//
// 典型行为��?//
//	时序:      |-- firstEventTimeout --|---- idleTimeout ----|---- idleTimeout ----|-->
//	事件��?    ...(等待)...            EventStart  TextDelta  TextDelta  ...    Done
type StreamTimeoutConfig struct {
	// FirstEventTimeout 从流开始到收到第一个事件的超时��?	// 设置��?0 或负值表示不限制（永不超时）��?	// 默认: 100s（推��?冷启动可能需要较长时间）
	FirstEventTimeout time.Duration

	// IdleTimeout 相邻两个事件之间的最大间隔��?	// 设置��?0 或负值表示不限制（永不超时）��?	// 默认: 120s
	IdleTimeout time.Duration

	// IsProgressItem 判断一个事件是否算��?进度事件"��?	// 进度事件会重��?idle 计时器；非进度事件（如心跳）不会��?	// ��?nil 时所有事件都算进度事件��?	IsProgressItem func(item any) bool
}

// DefaultStreamTimeoutConfig 适合大多��?LLM provider 的默认超时配置��?func DefaultStreamTimeoutConfig() StreamTimeoutConfig {
	return StreamTimeoutConfig{
		FirstEventTimeout: 100 * time.Second,
		IdleTimeout:       120 * time.Second,
		IsProgressItem:    nil, // 所有事件都算进��?	}
}

// TimeoutError 表示超时错误��?type TimeoutError struct {
	Kind    string // "first_event" ��?"idle"
	Timeout time.Duration
}

func (e *TimeoutError) Error() string {
	return fmt.Sprintf("stream %s timeout after %v", e.Kind, e.Timeout)
}

// IsTimeoutError 检查是否是超时错误��?func IsTimeoutError(err error) bool {
	var te *TimeoutError
	return errors.As(err, &te)
}

// ============================================================================
// 带超时的 EventStream 包装
//
// StreamWithTimeout 包装一��?EventStream，自动注入双阶段超时��?// 用法:
//
//	stream := NewEventStreamWithTimeout(rawStream, timeoutConfig)
//	msg, err := stream.ForEach(ctx, func(evt AssistantMessageEvent) error {
//	    fmt.Println(evt)
//	    return nil
//	})
//
// 与原��?EventStream.ForEach 的区��?
//   1. 首帧超时：第一个事件长时间不来会报��?//   2. 空闲超时：两个事件间隔过长会报错
//   3. 心跳/keepalive 不会被等同于"进度"
// ============================================================================

// StreamWithTimeout 包装 EventStream 添加超时控制��?type StreamWithTimeout[T any, R any] struct {
	stream *EventStream[T, R]
	config StreamTimeoutConfig
}

// NewEventStreamWithTimeout 创建一个超时中间件��?func NewEventStreamWithTimeout[T any, R any](
	stream *EventStream[T, R],
	config StreamTimeoutConfig,
) *StreamWithTimeout[T, R] {
	return &StreamWithTimeout[T, R]{
		stream: stream,
		config: config,
	}
}

// ForEach 遍历事件流，自动注入双阶段超时控制��?// 返回最终的 AssistantMessage（与原始 EventStream.ForEach 行为一致）��?//
// 注意：本方法已包含超时控制，请不要在同一��?EventStream 上同时调��?// StreamWithTimeout.ForEach 和原��?EventStream.ForEach��?func (w *StreamWithTimeout[T, R]) ForEach(ctx context.Context, handler func(T) error) (R, error) {
	firstEventReceived := false
	lastProgress := time.Now()

	for {
		// 计算本次竞选的超时时间
		var timeoutCh <-chan time.Time
		if !firstEventReceived && w.config.FirstEventTimeout > 0 {
			timeoutCh = time.After(w.config.FirstEventTimeout)
		} else if firstEventReceived && w.config.IdleTimeout > 0 {
			elapsed := time.Since(lastProgress)
			remaining := w.config.IdleTimeout - elapsed
			if remaining <= 0 {
				var zero R
				return zero, &TimeoutError{Kind: "idle", Timeout: w.config.IdleTimeout}
			}
			timeoutCh = time.After(remaining)
		}

		select {
		case <-ctx.Done():
			w.stream.Stop()
			var zero R
			return zero, ctx.Err()

		case <-timeoutCh:
			kind := "idle"
			timeout := w.config.IdleTimeout
			if !firstEventReceived {
				kind = "first_event"
				timeout = w.config.FirstEventTimeout
			}
			w.stream.Stop()
			var zero R
			return zero, &TimeoutError{Kind: kind, Timeout: timeout}

		case evt, ok := <-w.stream.Events():
			if !ok {
				return w.stream.Result()
			}
			if evt.done {
				if evt.err != nil {
					var zero R
					return zero, evt.err
				}
				return w.stream.Result()
			}

			// 标记首帧已到
			if !firstEventReceived {
				firstEventReceived = true
				lastProgress = time.Now()
			}

			// 判断是否重置 idle 计时��?			if w.config.IsProgressItem == nil || w.config.IsProgressItem(evt.value) {
				lastProgress = time.Now()
			}

			if err := handler(evt.value); err != nil {
				w.stream.Stop()
				var zero R
				return zero, err
			}
		}
	}
}

// ============================================================================
// 流式竞态中间件（Promise.race 模式��?//
// 参��?omp (packages/ai/src/utils/idle-iterator.ts) 的设计：
//   把超时、中断、数据三个信号通过 Promise.race 竞态��?//   ��?Go 中我们通过 select 实现，但提供更结构化的方式��?//
// Race 用于将超时、中断、数据三个信号统一处理��?// 每个 Next 调用都会返回一��?RaceResult，告知哪个信号胜出��?// ============================================================================

// RaceConfig 竞态配��?type RaceConfig struct {
	// PerEventTimeout 每个事件之间的最大等待时间��?	// 每次调用 Next() 都会重启这个计时器，因此这是"事件间空闲超��?��?	// 而非整个流的整体超时��? 表示无限制��?	PerEventTimeout time.Duration
	// Abort 可选的取消信号 channel��?	Abort <-chan struct{}
}

// Race ��?EventStream 上执行竞态迭代��?type Race[T any, R any] struct {
	stream *EventStream[T, R]
	config RaceConfig
}

// RaceResult 表示竞态结��?type RaceResult[T any] struct {
	// Item ��?Kind ��?RaceEvent 时有��?	Item T
	// Kind 表示竞态的赢家
	Kind RaceKind
	// Error ��?Kind ��?RaceError ��?RaceAbort 时有��?	Error error
}

// RaceKind 表示竞态的赢家
type RaceKind int

const (
	RaceEvent   RaceKind = iota // 正常数据事件
	RaceTimeout                 // 超时
	RaceDone                    // 流正常结��?	RaceAbort                   // 中断
	RaceError                   // 流错��?)

// NewRace 创建一个竞态迭代器��?func NewRace[T any, R any](stream *EventStream[T, R], config RaceConfig) *Race[T, R] {
	return &Race[T, R]{stream: stream, config: config}
}

// Next 等待下一个结果，返回时告知哪个信号胜出��?// 每次调用都会新建 PerEventTimeout 计时器，因此超时针对的是"两次 Next 调用的间��?��?// 可以多次调用直到返回 RaceDone ��?RaceError��?func (r *Race[T, R]) Next(ctx context.Context) RaceResult[T] {
	var timeoutCh <-chan time.Time
	if r.config.PerEventTimeout > 0 {
		timeoutCh = time.After(r.config.PerEventTimeout)
	}

	var abortCh <-chan struct{}
	if r.config.Abort != nil {
		abortCh = r.config.Abort
	}

	// 竞态：事件 vs 超时 vs 中断
	select {
	case <-ctx.Done():
		r.stream.Stop()
		return RaceResult[T]{Kind: RaceAbort, Error: ctx.Err()}

	case <-timeoutCh:
		r.stream.Stop()
		return RaceResult[T]{Kind: RaceTimeout}

	case <-abortCh:
		r.stream.Stop()
		return RaceResult[T]{Kind: RaceAbort}

	case evt, ok := <-r.stream.Events():
		if !ok {
			// channel 关闭，获取最终结��?			_, err := r.stream.Result()
			if err != nil {
				return RaceResult[T]{Kind: RaceError, Error: err}
			}
			return RaceResult[T]{Kind: RaceDone}
		}
		if evt.done {
			if evt.err != nil {
				return RaceResult[T]{Kind: RaceError, Error: evt.err}
			}
			return RaceResult[T]{Kind: RaceDone}
		}
		return RaceResult[T]{Item: evt.value, Kind: RaceEvent}
	}
}

// ============================================================================
// 便利函数：执行带超时的流式请��?// ============================================================================

// StreamWithTimeoutFn 执行一个流��?LLM 请求，返回带超时��?StreamWithTimeout 包装��?//
// 用法:
//
//	timeoutCfg := DefaultStreamTimeoutConfig()
//	timeoutCfg.FirstEventTimeout = 30 * time.Second
//	timeoutCfg.IdleTimeout = 60 * time.Second
//
//	wrapped, err := StreamWithTimeoutFn(ctx, timeoutCfg, func(ctx) (*EventStream[AssistantMessageEvent, AssistantMessage], error) {
//	    return provider.Stream(ctx, model, llmCtx, opts)
//	})
//	if err != nil { ... }
//	msg, err := wrapped.ForEach(ctx, handler)
func StreamWithTimeoutFn[T AssistantMessageEvent, R any](
	ctx context.Context,
	timeoutCfg StreamTimeoutConfig,
	streamFn func(context.Context) (*EventStream[T, R], error),
) (*StreamWithTimeout[T, R], error) {
	innerStream, err := streamFn(ctx)
	if err != nil {
		return nil, err
	}
	wrapped := NewEventStreamWithTimeout(innerStream, timeoutCfg)
	return wrapped, nil
}

// ============================================================================
// 超时配置的辅助函��?// ============================================================================

// WithFirstEventTimeout 设置首帧超时，返回副本��?func (c StreamTimeoutConfig) WithFirstEventTimeout(d time.Duration) StreamTimeoutConfig {
	c.FirstEventTimeout = d
	return c
}

// WithIdleTimeout 设置空闲超时，返回副本��?func (c StreamTimeoutConfig) WithIdleTimeout(d time.Duration) StreamTimeoutConfig {
	c.IdleTimeout = d
	return c
}

// Package openai implements OpenAI-compatible API providers.
package openai

import (
	"encoding/json"

	core "crux-ai/core"
)

const defaultCompletionsURL = "https://api.openai.com/v1"
const defaultResponsesURL = "https://api.openai.com/v1"

// ConvertMessages converts internal messages to OpenAI Chat Completions format.
func ConvertMessages(messages []core.Message, model core.Model) ([]map[string]any, error) {
	var result []map[string]any
	for _, msg := range messages {
		switch m := msg.(type) {
		case core.UserMessage:
			content, err := convertUserContent(m.Content)
			if err != nil {
				return nil, err
			}
			result = append(result, map[string]any{"role": "user", "content": content})
		case core.AssistantMessage:
			openaiMsg := map[string]any{"role": "assistant"}
			content, toolCalls := convertAssistantContentSplit(m.Content)
			if len(content) == 1 {
				if textBlock, ok := content[0].(map[string]any); ok && textBlock["type"] == "text" {
					openaiMsg["content"] = textBlock["text"]
				} else if len(content) > 0 {
					openaiMsg["content"] = content
				}
			} else if len(content) > 0 {
				openaiMsg["content"] = content
			}
			if len(toolCalls) > 0 {
				openaiMsg["tool_calls"] = toolCalls
			}
			result = append(result, openaiMsg)
		case core.ToolResultMessage:
			result = append(result, map[string]any{
				"role":         "tool",
				"tool_call_id": m.ToolCallID,
				"content":      convertToolResultContent(m.Content),
			})
		}
	}
	return result, nil
}

func convertUserContent(content any) (any, error) {
	switch c := content.(type) {
	case string:
		return c, nil
	case []core.ContentBlock:
		var blocks []any
		for _, block := range c {
			switch b := block.(type) {
			case core.TextContent:
				blocks = append(blocks, map[string]any{"type": "text", "text": b.Text})
			case core.ImageContent:
				blocks = append(blocks, map[string]any{
					"type": "image_url",
					"image_url": map[string]any{
						"url": "data:" + b.MimeType + ";base64," + b.Data,
					},
				})
			}
		}
		return blocks, nil
	default:
		return c, nil
	}
}

func convertAssistantContent(content []core.ContentBlock) []any {
	blocks, toolCalls := convertAssistantContentSplit(content)
	if len(toolCalls) > 0 {
		blocks = append(blocks, toolCalls...)
	}
	return blocks
}

// convertAssistantContentSplit separates text/thinking content from tool calls.
// This is needed for the OpenAI Chat Completions format where tool_calls must be
// a separate top-level field, not inside content.
func convertAssistantContentSplit(content []core.ContentBlock) (blocks []any, toolCalls []any) {
	for _, block := range content {
		switch b := block.(type) {
		case core.TextContent:
			blocks = append(blocks, map[string]any{"type": "text", "text": b.Text})
		case core.ThinkingContent:
			blocks = append(blocks, map[string]any{
				"type": "reasoning_content",
				"reasoning_content": map[string]any{"text": b.Thinking},
			})
		case core.ToolCall:
			toolCalls = append(toolCalls, map[string]any{
				"id":   b.ID,
				"type": "function",
				"function": map[string]any{
					"name":      b.Name,
					"arguments": string(b.Arguments),
				},
			})
		}
	}
	return blocks, toolCalls
}

func convertToolResultContent(content []core.ContentBlock) string {
	var parts []string
	for _, block := range content {
		if text, ok := block.(core.TextContent); ok {
			parts = append(parts, text.Text)
		}
	}
	return joinStrings(parts, "\n")
}

func joinStrings(parts []string, sep string) string {
	if len(parts) == 0 {
		return ""
	}
	if len(parts) == 1 {
		return parts[0]
	}
	result := parts[0]
	for _, p := range parts[1:] {
		result += sep + p
	}
	return result
}

// ConvertTools converts tools to OpenAI format.
func ConvertTools(tools []core.Tool) []map[string]any {
	result := make([]map[string]any, len(tools))
	for i, tool := range tools {
		t := map[string]any{
			"type": "function",
			"function": map[string]any{
				"name":        tool.Name,
				"description": tool.Description,
			},
		}
		if len(tool.Parameters) > 0 {
			var params map[string]any
			if err := json.Unmarshal(tool.Parameters, &params); err == nil {
				t["function"].(map[string]any)["parameters"] = params
			}
		}
		result[i] = t
	}
	return result
}

// MapStopReason maps OpenAI finish reasons to StopReason.
func MapStopReason(reason string) core.StopReason {
	switch reason {
	case "stop":
		return core.StopStop
	case "length":
		return core.StopLength
	case "tool_calls", "function_call":
		return core.StopToolUse
	default:
		return core.StopStop
	}
}

package openai

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strings"
	"time"

	core "crux-ai/core"
)

// ResponsesOptions holds OpenAI Responses-specific options.
type ResponsesOptions struct {
	ReasoningEffort  string `json:"reasoningEffort,omitempty"`
	ReasoningSummary string `json:"reasoningSummary,omitempty"`
	ServiceTier      string `json:"serviceTier,omitempty"`
}

// ResponsesProvider implements the OpenAI Responses API.
type ResponsesProvider struct{}

// NewResponses creates a new OpenAI Responses provider.
func NewResponses() *ResponsesProvider { return &ResponsesProvider{} }

func (p *ResponsesProvider) Stream(ctx context.Context, model core.Model, llmCtx core.Context, opts core.StreamOptions) (*core.AssistantMessageEventStream, error) {
	return streamResponses(ctx, model, llmCtx, opts, ResponsesOptions{})
}

func (p *ResponsesProvider) StreamSimple(ctx context.Context, model core.Model, llmCtx core.Context, opts core.SimpleStreamOptions) (*core.AssistantMessageEventStream, error) {
	responsesOpts := ResponsesOptions{}
	if opts.Reasoning != "" {
		responsesOpts.ReasoningEffort = string(clampEffort(opts.Reasoning))
	}
	return streamResponses(ctx, model, llmCtx, opts.StreamOptions, responsesOpts)
}

func streamResponses(ctx context.Context, model core.Model, c core.Context, opts core.StreamOptions, responsesOpts ResponsesOptions) (*core.AssistantMessageEventStream, error) {
	apiKey := core.ResolveAPIKey(model.Provider, opts.APIKey)
	if apiKey == "" {
		return nil, fmt.Errorf("openai-responses: no API key provided")
	}
	baseURL := model.BaseURL
	if baseURL == "" {
		baseURL = defaultResponsesURL
	}

	body, err := buildResponsesBody(model, c, opts, responsesOpts)
	if err != nil {
		return nil, fmt.Errorf("openai-responses: failed to build request: %w", err)
	}
	if opts.OnPayload != nil {
		opts.OnPayload(body)
	}

	stream := core.NewEventStream[core.AssistantMessageEvent, core.AssistantMessage]()

	go func() {
		defer func() {
			if r := recover(); r != nil {
				stream.Error(fmt.Errorf("openai-responses: panic: %v", r))
			}
		}()
		msg, err := doResponsesStream(ctx, baseURL, apiKey, model, body, stream, opts)
		if err != nil {
			stream.Error(err)
			return
		}
		stream.End(msg)
	}()

	return stream, nil
}

func buildResponsesBody(model core.Model, c core.Context, opts core.StreamOptions, responsesOpts ResponsesOptions) (map[string]any, error) {
	body := map[string]any{
		"model":  model.ID,
		"stream": true,
	}
	if opts.MaxTokens != nil && *opts.MaxTokens > 0 {
		body["max_output_tokens"] = *opts.MaxTokens
	} else if model.MaxTokens > 0 {
		body["max_output_tokens"] = model.MaxTokens
	}
	if opts.Temperature != nil {
		body["temperature"] = *opts.Temperature
	}

	input := []map[string]any{}
	if c.SystemPrompt != "" {
		input = append(input, map[string]any{"role": "system", "content": c.SystemPrompt})
	}
	msgs, err := convertResponsesMessages(c.Messages)
	if err != nil {
		return nil, err
	}
	input = append(input, msgs...)
	body["input"] = input

	if len(c.Tools) > 0 {
		body["tools"] = convertResponsesTools(c.Tools)
	}
	if responsesOpts.ReasoningEffort != "" {
		reasoning := map[string]any{"effort": responsesOpts.ReasoningEffort}
		if responsesOpts.ReasoningSummary != "" {
			reasoning["summary"] = responsesOpts.ReasoningSummary
		}
		body["reasoning"] = reasoning
	}
	if responsesOpts.ServiceTier != "" {
		body["service_tier"] = responsesOpts.ServiceTier
	}
	return body, nil
}

func convertResponsesMessages(messages []core.Message) ([]map[string]any, error) {
	var result []map[string]any
	for _, msg := range messages {
		switch m := msg.(type) {
		case core.UserMessage:
			content, err := convertUserContent(m.Content)
			if err != nil {
				return nil, err
			}
			result = append(result, map[string]any{"role": "user", "content": content})
		case core.AssistantMessage:
			for _, block := range m.Content {
				switch b := block.(type) {
				case core.TextContent:
					result = append(result, map[string]any{
						"type": "message", "role": "assistant",
						"content": []any{map[string]any{"type": "output_text", "text": b.Text}},
					})
				case core.ToolCall:
					result = append(result, map[string]any{
						"type": "function_call", "id": b.ID, "name": b.Name,
						"arguments": string(b.Arguments), "call_id": b.ID,
					})
				}
			}
		case core.ToolResultMessage:
			content := convertToolResultContent(m.Content)
			result = append(result, map[string]any{
				"type": "function_call_output", "call_id": m.ToolCallID, "output": content,
			})
		}
	}
	return result, nil
}

func convertResponsesTools(tools []core.Tool) []map[string]any {
	result := make([]map[string]any, len(tools))
	for i, tool := range tools {
		t := map[string]any{
			"type":        "function",
			"name":        tool.Name,
			"description": tool.Description,
		}
		if len(tool.Parameters) > 0 {
			var params map[string]any
			if err := json.Unmarshal(tool.Parameters, &params); err == nil {
				t["parameters"] = params
			}
		}
		result[i] = t
	}
	return result
}

func doResponsesStream(ctx context.Context, baseURL, apiKey string, model core.Model, body map[string]any, stream *core.AssistantMessageEventStream, opts core.StreamOptions) (core.AssistantMessage, error) {
	bodyBytes, err := json.Marshal(body)
	if err != nil {
		return core.AssistantMessage{}, err
	}
	url := baseURL + "/responses"

	req, err := http.NewRequestWithContext(ctx, "POST", url, bytes.NewReader(bodyBytes))
	if err != nil {
		return core.AssistantMessage{}, err
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", "Bearer "+apiKey)
	for k, v := range model.Headers {
		req.Header.Set(k, v)
	}
	for k, v := range opts.Headers {
		req.Header.Set(k, v)
	}

	client := core.NewTimeoutClient(opts.TimeoutMs)
	resp, err := client.Do(req)
	if err != nil {
		return core.AssistantMessage{}, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		bodyBytes, _ := io.ReadAll(resp.Body)
		return core.AssistantMessage{}, fmt.Errorf("openai-responses: API error %d: %s", resp.StatusCode, string(bodyBytes))
	}
	return processResponsesSSE(resp.Body, stream, model, opts)
}

func processResponsesSSE(body io.Reader, stream *core.AssistantMessageEventStream, model core.Model, opts core.StreamOptions) (core.AssistantMessage, error) {
	scanner := bufio.NewScanner(body)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	var (
		msg       core.AssistantMessage
		textBuf   strings.Builder
		toolCalls map[string]*core.ToolCall
	)
	msg.API = model.API
	msg.Provider = model.Provider
	msg.Model = model.ID
	msg.Role = "assistant"
	msg.Timestamp = time.Now()
	toolCalls = make(map[string]*core.ToolCall)

	stream.Push(core.EventStart{Type: "start", API: model.API, Provider: model.Provider, Model: model.ID, Timestamp: time.Now()})

	for scanner.Scan() {
		line := scanner.Text()
		if !strings.HasPrefix(line, "data: ") {
			continue
		}
		data := strings.TrimPrefix(line, "data: ")
		if data == "[DONE]" {
			break
		}
		if opts.OnResponse != nil {
			opts.OnResponse(data)
		}
		var event map[string]any
		if err := json.Unmarshal([]byte(data), &event); err != nil {
			continue
		}
		eventType, _ := event["type"].(string)

		switch eventType {
		case "response.created":
			response, _ := event["response"].(map[string]any)
			if response != nil {
				if usage, ok := response["usage"].(map[string]any); ok {
					msg.Usage.Input = int(getFloat(usage, "input_tokens"))
					msg.Usage.Output = int(getFloat(usage, "output_tokens"))
				}
			}
		case "response.output_item.added":
			item, _ := event["item"].(map[string]any)
			if item != nil {
				if itemType, _ := item["type"].(string); itemType == "function_call" {
					id, _ := item["id"].(string)
					name, _ := item["name"].(string)
					callID, _ := item["call_id"].(string)
					toolCalls[callID] = &core.ToolCall{Type: "toolCall", ID: id, Name: name}
					stream.Push(core.EventToolCallStart{Type: "toolcall_start", ID: id, Name: name})
				}
			}
		case "response.output_text.delta":
			delta, _ := event["delta"].(string)
			if delta != "" {
				textBuf.WriteString(delta)
				stream.Push(core.EventTextDelta{Type: "text_delta", Delta: delta})
			}
		case "response.function_call_arguments.delta":
			callID, _ := event["call_id"].(string)
			delta, _ := event["delta"].(string)
			if tc, ok := toolCalls[callID]; ok && delta != "" {
				tc.Arguments = append(tc.Arguments, []byte(delta)...)
				stream.Push(core.EventToolCallDelta{Type: "toolcall_delta", ID: tc.ID, ArgumentsDelta: delta})
			}
		case "response.function_call_arguments.done":
			callID, _ := event["call_id"].(string)
			if tc, ok := toolCalls[callID]; ok {
				stream.Push(core.EventToolCallEnd{Type: "toolcall_end", ID: tc.ID, Arguments: tc.Arguments})
				msg.Content = append(msg.Content, *tc)
			}
		case "response.completed":
			response, _ := event["response"].(map[string]any)
			if response != nil {
				if usage, ok := response["usage"].(map[string]any); ok {
					msg.Usage.Input = int(getFloat(usage, "input_tokens"))
					msg.Usage.Output = int(getFloat(usage, "output_tokens"))
				}
				if status, ok := response["status"].(string); ok {
					msg.StopReason = mapResponseStatus(status)
				}
			}
		}
	}

	if textBuf.Len() > 0 {
		msg.Content = append(msg.Content, core.TextContent{Type: "text", Text: textBuf.String()})
		stream.Push(core.EventTextEnd{Type: "text_end"})
	}

	msg.Usage.TotalTokens = msg.Usage.Input + msg.Usage.Output
	msg.Usage.Cost = core.CalculateCost(model, msg.Usage)
	stream.Push(core.EventDone{Type: "done", Message: msg})

	if err := scanner.Err(); err != nil {
		return msg, fmt.Errorf("openai-responses: SSE read error: %w", err)
	}
	return msg, nil
}

func mapResponseStatus(status string) core.StopReason {
	switch status {
	case "completed":
		return core.StopStop
	case "incomplete":
		return core.StopLength
	case "failed":
		return core.StopError
	case "cancelled":
		return core.StopAborted
	default:
		return core.StopStop
	}
}

