	model := Model{
		Cost: Cost{Input: 3.0, Output: 15.0},
	}
	usage := Usage{}

	cost := CalculateCost(model, usage)
	if cost.Total != 0 {
		t.Errorf("Expected zero cost, got %f", cost.Total)
	}
}

